3	import * as React from "react";
4	import { useTransition } from "react";
5	import { Check, Ban, ShieldAlert } from "lucide-react";
6	import { Card } from "@/components/ui/Card";
7	import { Button } from "@/components/ui/Button";
8	import { StatusBadge } from "@/components/ui/StatusBadge";
9	import { resolveReport, setUserSuspended } from "@/app/(admin)/admin/actions";
10	import { t } from "@/lib/i18n";
11	import { useToast } from "@/components/ui/Toast";
12	
13	export interface ReportItem {
14	  id: string;
15	  reason: string;
16	  status: "open" | "reviewed";
17	  whenLabel: string;
18	  reporterName: string;
19	  targetId: string | null;
20	  targetName: string | null;
21	}
22	
23	export function ReportCard({ report }: { report: ReportItem }) {
24	  const [pending, startTransition] = useTransition();
25	  const { announce, toast } = useToast();
26	
27	  function review() {
28	    startTransition(async () => {
29	      const res = await resolveReport(report.id);
30	      if (!res.ok) {
31	        toast(t("admin.decisionError"), "alert");
32	        return;
33	      }
34	      announce(t("admin.reportReviewed"), true);
35	    });
36	  }
37	
38	  function suspendTarget() {
39	    if (!report.targetId) return;
40	    startTransition(async () => {
41	      const res = await setUserSuspended({
42	        userId: report.targetId!,
43	        suspended: true,
44	      });
45	      if (!res.ok) {
46	        toast(t("admin.decisionError"), "alert");
47	        return;
48	      }
49	      announce(
50	        t("admin.userSuspended", { name: report.targetName ?? "user" }),
51	        true,
52	      );
53	    });
54	  }
55	
56	  return (
57	    <Card as="li" className="flex flex-col gap-3">
58	      <div className="flex flex-wrap items-center justify-between gap-3">
59	        <span className="flex items-center gap-2 text-base font-bold text-ink">
60	          <ShieldAlert size={18} strokeWidth={2} aria-hidden="true" className="text-alert" />
61	          {t("admin.reportReporter")}: {report.reporterName}
62	          {report.targetName ? (
63	            <span className="text-ink-soft">
64	              {" · "}
65	              {t("admin.reportTarget")}: {report.targetName}
66	            </span>
67	          ) : null}
68	        </span>
69	        <StatusBadge tone={report.status === "open" ? "warning" : "success"}>
70	          {report.status === "open"
71	            ? t("admin.reportStatusOpen")
72	            : t("admin.reportStatusReviewed")}
73	        </StatusBadge>
74	      </div>
75	
76	      <p className="text-base text-ink">{report.reason}</p>
77	      <p className="text-sm text-ink-soft">
78	        {t("admin.reportWhen")}: {report.whenLabel}
79	      </p>
80	
81	      <div className="flex flex-wrap gap-3 border-t border-border pt-3">
82	        {report.status === "open" ? (
83	          <Button
84	            icon={Check}
85	            onClick={review}
86	            disabled={pending}
87	            aria-label={t("admin.reportReviewAria", { name: report.reporterName })}
88	          >
89	            {t("admin.reportReview")}
90	          </Button>
91	        ) : null}
92	        {report.targetId ? (
93	          <Button
94	            variant="danger"
95	            icon={Ban}
96	            onClick={suspendTarget}
97	            disabled={pending}
98	            aria-label={t("admin.reportSuspendTargetAria", {
99	              name: report.targetName ?? report.reporterName,
100	            })}
101	          >
102	            {t("admin.reportSuspendTarget")}
103	          </Button>
104	        ) : null}
105	      </div>
106	    </Card>
107	  );
108	}
